_OCTAL_ESCAPES = re.compile(r'(?:\\[0-7]{1,3})+')


def _octal_unescape_char(match):
    """Replace _OCTAL_ESCAPES with their expansion"""
    text = match.group(0)
    assert text[0] == '\\'
