      ssize_t n = TEMP_FAILURE_RETRY (read (fd,
                                            (char *) command + offset,
                                            sizeof (*command) - offset));

      if (n < 0)
        return -1;
      if (n == 0)
        return 0;

      offset += n;
    }

  return 1;
}

