static void
send_status (int         fd,
             char        status,
             const char *message)
{
  char header[2] = { status, 0 };
  uint32_t len = message != NULL ? (uint32_t) strlen (message) : 0;

  if (!write_all (fd, header, 1))
    return;
  if (!write_all (fd, (const char *) &len, sizeof (len)))
    return;
  if (len > 0)
    (void) write_all (fd, message, len);
}

static char *
