static int
read_command (int           fd,
              CgroupCommand *command)
{
  size_t offset = 0;

  while (offset < sizeof (*command))
    {
      ssize_t n = TEMP_FAILURE_RETRY (read (fd,
                                            (char *) command + offset,
                                            sizeof (*command) - offset));

      if (n < 0)
        return -1;
      if (n == 0)
        return 0;

      offset += n;
    }

  return 1;
}

